var ajustes = $('Buscar Ajustes Negativos').first().json.result || [];
var salidas = $('Buscar Salidas Sin Venta').first().json.result || [];
var params = $('Calcular Ventana de Tiempo').first().json;

if (ajustes.length === 0 && salidas.length === 0) return [];

// ── SECCIÓN 1: Ajustes manuales directos (sin picking = injustificados) ──
var secAjustes = '';
if (ajustes.length > 0) {
  var filasAj = '';
  ajustes.forEach(function(m, i) {
    var bg = i % 2 === 0 ? '#ffffff' : '#fff5f5';
    var producto = m.product_id ? m.product_id[1] : 'N/A';
    var ubicacion = m.location_id ? m.location_id[1] : 'N/A';
    var empresa = m.company_id ? m.company_id[1] : 'N/A';
    var usuario = m.write_uid ? m.write_uid[1] : 'Desconocido';
    var cantidad = parseFloat(m.quantity) || 0;
    var fecha = (m.date || '').substring(0, 16).replace('T', ' ');
    var origen = m.origin || '—';
    var tienePicking = m.picking_id && m.picking_id !== false;
    var justificacion = tienePicking
      ? '<span style="color:#28a745;font-size:11px;">✅ Con picking</span>'
      : '<span style="color:#dc3545;font-weight:700;font-size:11px;">🚨 SIN JUSTIFICACIÓN</span>';

    filasAj += '<tr style="background:' + bg + '">' +
      '<td style="padding:8px 10px;border:1px solid #f5c6cb;font-size:12px;white-space:nowrap;">' + fecha + '</td>' +
      '<td style="padding:8px 10px;border:1px solid #f5c6cb;font-size:12px;">' + empresa + '</td>' +
      '<td style="padding:8px 10px;border:1px solid #f5c6cb;">' + producto + '</td>' +
      '<td style="padding:8px 10px;border:1px solid #f5c6cb;font-size:12px;">' + ubicacion + '</td>' +
      '<td style="padding:8px 10px;border:1px solid #f5c6cb;text-align:center;font-weight:700;color:#dc3545;">-' + cantidad.toFixed(2) + '</td>' +
      '<td style="padding:8px 10px;border:1px solid #f5c6cb;font-size:12px;color:#777;">' + origen + '</td>' +
      '<td style="padding:8px 10px;border:1px solid #f5c6cb;font-size:12px;">' + justificacion + '</td>' +
      '<td style="padding:8px 10px;border:1px solid #f5c6cb;font-size:12px;color:#555;">' + usuario + '</td>' +
      '</tr>';
  });

  secAjustes = '<div style="margin-bottom:28px;">' +
    '<h3 style="color:#dc3545;margin:0 0 8px;font-size:15px;">🔻 Reducciones de stock por ajuste manual (' + ajustes.length + ')</h3>' +
    '<p style="font-size:12px;color:#888;margin:0 0 10px;">Movimientos hacia la ubicación virtual de inventario. Los marcados 🚨 no tienen ningún documento de respaldo.</p>' +
    '<table style="width:100%;border-collapse:collapse;font-size:13px;">' +
    '<thead><tr style="background:#dc3545;color:#fff;">' +
    '<th style="padding:9px 10px;text-align:left;">Fecha</th>' +
    '<th style="padding:9px 10px;text-align:left;">Empresa</th>' +
    '<th style="padding:9px 10px;text-align:left;">Producto</th>' +
    '<th style="padding:9px 10px;text-align:left;">Ubicación</th>' +
    '<th style="padding:9px 10px;text-align:center;">Cantidad</th>' +
    '<th style="padding:9px 10px;text-align:left;">Origen</th>' +
    '<th style="padding:9px 10px;text-align:left;">Justificación</th>' +
    '<th style="padding:9px 10px;text-align:left;">Responsable</th>' +
    '</tr></thead>' +
    '<tbody>' + filasAj + '</tbody></table></div>';
} else {
  secAjustes = '<div style="margin-bottom:28px;"><p style="color:#28a745;font-size:13px;">✅ Sin reducciones de stock por ajuste manual.</p></div>';
}

// ── SECCIÓN 2: Salidas con picking pero sin orden de venta ───
var secSalidas = '';
if (salidas.length > 0) {
  var filasS = '';
  salidas.forEach(function(p, i) {
    var bg = i % 2 === 0 ? '#ffffff' : '#fff8e1';
    var empresa = p.company_id ? p.company_id[1] : 'N/A';
    var responsable = p.user_id ? p.user_id[1] : 'Desconocido';
    var cliente = p.partner_id ? p.partner_id[1] : '—';
    var origen = p.origin || '⚠️ Sin origen';
    var fecha = (p.date_done || '').substring(0, 16).replace('T', ' ');
    var sinOrigen = !p.origin;
    var origenStyle = sinOrigen ? 'font-weight:700;color:#e67e00;' : 'color:#555;';

    filasS += '<tr style="background:' + bg + '">' +
      '<td style="padding:8px 10px;border:1px solid #ffd700;font-size:12px;white-space:nowrap;">' + fecha + '</td>' +
      '<td style="padding:8px 10px;border:1px solid #ffd700;font-size:12px;">' + empresa + '</td>' +
      '<td style="padding:8px 10px;border:1px solid #ffd700;font-weight:600;">' + p.name + '</td>' +
      '<td style="padding:8px 10px;border:1px solid #ffd700;font-size:12px;">' + cliente + '</td>' +
      '<td style="padding:8px 10px;border:1px solid #ffd700;font-size:12px;' + origenStyle + '">' + origen + '</td>' +
      '<td style="padding:8px 10px;border:1px solid #ffd700;font-size:12px;color:#555;">' + responsable + '</td>' +
      '</tr>';
  });

  secSalidas = '<div style="margin-bottom:28px;">' +
    '<h3 style="color:#e67e00;margin:0 0 8px;font-size:15px;">⚠️ Salidas de mercancía sin orden de venta (' + salidas.length + ')</h3>' +
    '<p style="font-size:12px;color:#888;margin:0 0 10px;">Despachos validados sin pedido de venta asociado. Revisa el campo <strong>Origen</strong> — si está vacío es especialmente sospechoso.</p>' +
    '<table style="width:100%;border-collapse:collapse;font-size:13px;">' +
    '<thead><tr style="background:#e67e00;color:#fff;">' +
    '<th style="padding:9px 10px;text-align:left;">Fecha</th>' +
    '<th style="padding:9px 10px;text-align:left;">Empresa</th>' +
    '<th style="padding:9px 10px;text-align:left;">Referencia</th>' +
    '<th style="padding:9px 10px;text-align:left;">Cliente</th>' +
    '<th style="padding:9px 10px;text-align:left;">Origen</th>' +
    '<th style="padding:9px 10px;text-align:left;">Responsable</th>' +
    '</tr></thead>' +
    '<tbody>' + filasS + '</tbody></table></div>';
} else {
  secSalidas = '<div style="margin-bottom:28px;"><p style="color:#28a745;font-size:13px;">✅ Todas las salidas tienen orden de venta asociada.</p></div>';
}

var nivelAlerta = (ajustes.length > 0 && salidas.length > 0) ? '🚨 ALERTA MÁXIMA' :
  ajustes.length > 0 ? '🔻 Ajuste sospechoso' : '⚠️ Salida sin venta';

return [{ json: {
  secAjustes: secAjustes,
  secSalidas: secSalidas,
  totalAjustes: ajustes.length,
  totalSalidas: salidas.length,
  nivelAlerta: nivelAlerta,
  now_label: params.now_label
} }];
